package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaViDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma Bika Asbahna", "Ôi Allah, nhờ Ngài mà chúng con bước vào buổi sáng và nhờ Ngài chúng con bước vào buổi tối; nhờ Thầy mà chúng tôi sống và cũng nhờ Thầy mà chúng tôi chết, và sự sống lại đối với Thầy.", "Vào buổi sáng.", "Nhà tiên tri ﷺ đã dạy các bạn đồng hành nói vào buổi sáng và buổi tối này."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma Bika Amsayna", "Ôi Allah, nhờ Ngài mà chúng con bước vào buổi tối và nhờ Ngài chúng con bước vào buổi sáng; nhờ Chúa mà chúng con sống và cũng nhờ Chúa mà chúng con chết, và trở về với Chúa.", "Vào buổi tối.", "Nhà tiên tri ﷺ đã dạy các bạn đồng hành nói vào buổi sáng và buổi tối này."),
        "dua_afiyah_morning" to DuaText("Yêu cầu Afiyah", "Ôi Allah, tôi cầu xin Ngài sự tha thứ và hạnh phúc ở thế giới này và Đời sau.", "Nhà tiên tri ﷺ không bao giờ rời khỏi thời điểm này, dù sáng hay tối.", "Không ai được ban cho điều gì tốt hơn hạnh phúc."),
        "dua_afini_fi_badani" to DuaText("Sức khỏe cơ thể, thính giác và thị giác", "Ôi Allah, ban phúc lành cho cơ thể tôi. Ôi Allah, ban phúc lành cho thính giác của tôi. Ôi Allah, ban phúc lành cho tầm nhìn của tôi. Không có thần nào ngoại trừ Bạn.", "Ba lần mỗi sáng và tối.", "Một sự kết hợp cho sức khỏe và bảo vệ các giác quan."),
        "dua_ya_hayyu_aslih" to DuaText("Khắc phục mọi vấn đề của tôi", "Hỡi Đấng hằng sống, Hỡi Đấng duy trì, nhờ lòng thương xót của Ngài, tôi tìm kiếm sự giúp đỡ: sắp xếp mọi công việc của tôi và đừng bỏ mặc tôi dù chỉ trong chớp mắt.", "Nhà tiên tri ﷺ khuyên Fatimah (RA) nên nói điều đó vào buổi sáng và buổi tối.", "Yêu cầu sự giúp đỡ của Allah trong mọi vấn đề."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Tasbeeh của Juwayriyah (RA)", "Vinh quang thay Allah và mọi lời ca tụng đều thuộc về Ngài - bao nhiêu tùy theo sự sáng tạo của Ngài, bao nhiêu tùy theo mức độ Ngài hài lòng, tương đương với sức nặng của ngai vàng và mực của lời nói của Ngài.", "Ba lần vào buổi sáng - nặng nề hơn hàng giờ tập dhikr.", "Nói bốn cụm từ này ba lần có giá trị hơn dhikr từ bình minh cho đến giữa buổi sáng."),
        "dua_salawat" to DuaText("Durood-e-Ibrahimi", "Ôi Allah, hãy gửi lời cầu nguyện cho Muhammad ﷺ và gia đình Muhammad cũng như Ngài đã gửi lời cầu nguyện cho Ibrahim (AS) và gia đình Ibrahim; Bạn thật đáng khen ngợi, thật vinh quang. Ôi Allah, hãy phù hộ cho Muhammad ﷺ và gia đình Muhammad cũng như Ngài đã ban phước cho Ibrahim (AS) và gia đình Ibrahim; Bạn thật đáng khen ngợi, thật vinh quang.", "Salawat nói với Nhà tiên tri ﷺ trong lời cầu nguyện mọi lúc.", "Ai gửi salawat một lần, Allah sẽ gửi mười ân huệ cho người đó (Hồi giáo 408)."),
        "dua_wudu_after" to DuaText("Sau Võ Đô", "Tôi làm chứng rằng không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác, và rằng Muhammad ﷺ là người hầu và Sứ giả của Ngài. Lạy Allah, hãy khiến tôi trở thành một trong những người ăn năn và thanh lọc bản thân.", "Sau khi hoàn thành wudu.", "Tám cánh cổng Thiên đường được mở ra để anh ta có thể bước vào bất cứ ai anh ta muốn."),
        "dua_wudu_before" to DuaText("Trước Võ Đô", "Nhân danh Allah.", "Khi bắt đầu wudu.", "Không có wudu (hoàn chỉnh) nào dành cho người không đề cập đến tên của Allah trên đó."),
        "dua_istiftah" to DuaText("Lời cầu nguyện mở đầu (Sana)", "Lạy Allah, xin vinh danh Ngài và ca ngợi Ngài. Phước thay danh Ngài, tôn cao thay uy nghi của Ngài, và không có thần nào ngoại trừ Ngài.", "Khi bắt đầu lời cầu nguyện, ngay sau phần mở đầu takbir.", "Đoạn mở đầu Sunnah của lời cầu nguyện."),
        "dua_ruku" to DuaText("trong Ruku", "Vinh quang thay Chúa của tôi, Đấng vĩ đại.", "Ít nhất ba lần trong ruku.", "Sunnah tasbih của ruku."),
        "dua_sujood" to DuaText("ở Sujood", "Vinh quang thay Chúa của tôi, Đấng Tối Cao.", "Ít nhất ba lần trong sujood.", "Người hầu gần Chúa nhất khi đang lễ lạy (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Vươn lên từ Ruku", "Allah nghe thấy người ca ngợi Ngài. Lạy Chúa, mọi lời ca ngợi đều thuộc về Ngài.", "Trong khi đứng dậy từ ruku và đứng thẳng.", "'Rabbana wa lakal-hamd' của ai trùng với của các thiên thần thì tội lỗi trong quá khứ của người đó sẽ được tha thứ."),
        "dua_between_sajdas" to DuaText("Giữa hai Sajdas", "Chúa ơi, hãy tha thứ cho tôi. Chúa ơi, hãy tha thứ cho tôi.", "Khi ngồi giữa hai lễ lạy.", "Sunnah dua của việc ngồi giữa lễ lạy."),
        "dua_before_salam_four" to DuaText("Quy Y Bốn Điều (Trước Salam)", "Ôi Allah, tôi cầu xin Ngài nơi ẩn náu khỏi sự trừng phạt của Địa ngục, khỏi sự trừng phạt của nấm mộ, khỏi những thử thách của sự sống và cái chết, và khỏi sự xấu xa của cuộc xét xử Đấng Mê-si giả (Dajjal).", "Sau tashahhud và salawat cuối cùng, trước salam.", "Nhà tiên tri ﷺ đã ra lệnh phải tìm nơi ẩn náu khỏi bốn điều này."),
        "dua_qunoot_witr" to DuaText("Qunoot ở Witr", "Ôi Allah, hãy hướng dẫn tôi trong số những người mà Ngài đã hướng dẫn, ban cho tôi sự thịnh vượng trong số những người mà Ngài đã ban cho hạnh phúc, hãy đưa tôi đến sự chăm sóc của Ngài trong số những người mà Ngài đã chăm sóc, ban phước cho tôi với những gì Ngài đã ban cho và bảo vệ tôi khỏi sự xấu xa của những gì Ngài đã ra lệnh. Bạn ra lệnh và không có quyết định nào chống lại Bạn, và người bạn kết bạn không bao giờ bị sỉ nhục. Phước thay và tôn vinh Ngài, Chúa chúng con.", "Trong lời cầu nguyện Witr - Nhà tiên tri ﷺ đã dạy điều đó cho Hasan ibn Ali (RA).", "Sunnah qunoot của witr. (Trong số những người Hanafis, 'Allahumma inna nasta'inuka' cũng được biết đến nhiều.)"),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Inna Nasta'inuka)", "Ôi Allah, chúng tôi cầu xin sự giúp đỡ và sự tha thứ của Ngài, chúng tôi tin tưởng vào Ngài và trông cậy vào Ngài, chúng tôi ca ngợi Ngài theo cách tốt nhất, chúng tôi cảm ơn Ngài và không vô ơn, và chúng tôi bỏ rơi bất cứ ai không vâng lời Ngài. Ôi Allah, chúng tôi tôn thờ một mình Ngài, chúng tôi cầu nguyện và phủ phục trước Ngài, chúng tôi vội vã và phấn đấu hướng tới Ngài, chúng tôi hy vọng vào lòng thương xót của Ngài và sợ hãi sự trừng phạt của Ngài; chắc chắn sự trừng phạt của Ngài sẽ đến với những kẻ không có đức tin.", "Trong witr - việc thực hành của Hanafis.", "Báo cáo từ Umar (RA) trong qunoot."),
        "dua_sleep_aslamtu" to DuaText("Lời cuối trước khi ngủ", "Ôi Allah, tôi phục tùng Ngài, giao phó công việc của tôi cho Ngài và phó thác lưng cho sự bảo vệ của Ngài vì hy vọng vào Ngài và sợ hãi Ngài. Không có nơi nương tựa và lối thoát nào khỏi Bạn ngoại trừ Bạn. Con tin vào Kinh Thánh mà Ngài đã mặc khải và vào Đấng Tiên Tri mà Ngài đã sai đến.", "Sau wudu, nằm nghiêng bên phải - những lời cuối cùng trước khi ngủ.", "Nếu anh ta chết vào đêm đó, anh ta sẽ chết theo fitrah (Hồi giáo)."),
        "dua_waking_night" to DuaText("Thức dậy vào ban đêm", "Không ai có quyền được tôn thờ ngoại trừ Allah, một mình, không có đối tác. Ngài là quyền thống trị và Ngài là sự ca ngợi, và Ngài có quyền trên mọi sự. Mọi lời ca ngợi đều dành cho Allah, vinh quang thay Allah, không ai có quyền được tôn thờ ngoại trừ Allah, Allah là Đấng Vĩ đại nhất, và không có sức mạnh hay quyền năng nào ngoại trừ Allah. Ôi Allah, hãy tha thứ cho tôi.", "Khi thức dậy vào ban đêm.", "Dua của anh ấy đã được đáp lại, và nếu anh ấy làm wudu và cầu nguyện, lời cầu nguyện của anh ấy sẽ được chấp nhận."),
        "dua_hamm_ibn_masud" to DuaText("Dua cho nỗi đau buồn (Ibn Mas'ud)", "Ôi Allah, tôi là tôi tớ của Ngài, con trai của tôi tớ Ngài, con trai của tôi tớ Ngài. Tóc trước của tôi nằm trong tay bạn, mệnh lệnh của bạn đối với tôi được thực hiện, và sắc lệnh của bạn đối với tôi là công bằng. Tôi cầu xin Ngài bằng mọi cái tên thuộc về Ngài mà Ngài đã đặt tên cho mình, hoặc được mặc khải trong Thánh kinh của Ngài, hoặc được dạy cho bất kỳ tạo vật nào của Ngài, hoặc được Ngài lưu giữ trong kiến ​​thức về những điều vô hình - rằng Ngài biến Kinh Qur'an trở thành mùa xuân của trái tim tôi, ánh sáng trong lồng ngực tôi, xóa bỏ nỗi buồn và xua tan nỗi lo lắng của tôi.", "Trong đau buồn và đau khổ - Allah thay thế nỗi đau buồn bằng niềm vui.", "Allah loại bỏ sự lo lắng và đau buồn của anh ấy và ban cho anh ấy niềm vui thay vào đó."),
        "dua_difficulty_sahl" to DuaText("Khi có điều gì đó khó khăn", "Ôi Allah, không có gì là dễ dàng ngoại trừ những gì Ngài làm cho dễ dàng, và Ngài làm cho việc khó khăn trở nên dễ dàng nếu Ngài muốn.", "Khi cảm thấy có điều gì đó khó khăn.", "Dễ dàng trong các kỳ thi và nhiệm vụ khó khăn."),
        "dua_musibah" to DuaText("Khi một tai họa (Istirja)", "Chúng ta thuộc về Allah và chúng ta sẽ trở về với Ngài. Ôi Allah, hãy thưởng cho tôi trong cơn hoạn nạn và thay thế nó bằng thứ gì đó tốt hơn cho tôi.", "Khi có bất kỳ mất mát hoặc thiên tai nào.", "Allah chắc chắn sẽ ban điều gì đó tốt hơn - Umm Salamah (RA) đã được trao cho Nhà tiên tri ﷺ."),
        "dua_debt" to DuaText("Để thoát khỏi nợ nần", "Ôi Allah, hãy đáp ứng đủ cho tôi những gì Ngài đã quy định là hợp pháp chống lại những gì Ngài đã coi là bất hợp pháp, và bằng sự hào phóng của Ngài, hãy khiến tôi độc lập với tất cả mọi người ngoài Ngài.", "Để trả hết nợ - được dạy bởi Ali (RA).", "Dù món nợ có lớn như núi thì Allah cũng sẽ giải quyết."),
        "dua_anger" to DuaText("Khi tức giận", "Tôi cầu xin Allah che chở khỏi Shaytan, kẻ đáng nguyền rủa.", "Khi tức giận.", "Nhà tiên tri ﷺ đã nói: nếu anh ta nói điều này, cơn giận của anh ta sẽ biến mất."),
        "dua_waswasa" to DuaText("Chống lại Waswasa trong đức tin", "Tôi tin vào Allah và các Sứ giả của Ngài.", "Khi những lời thì thầm của Satan về đức tin vang lên.", "Khi lời thì thầm đến, hãy nói điều này và dừng lại ở đó (và cũng tìm nơi ẩn náu nơi Allah)."),
        "dua_travel_full" to DuaText("Đơn xin du lịch hoàn chỉnh", "Ôi Allah, chúng con cầu xin Ngài trong cuộc hành trình này sự công bình, lòng đạo đức và những việc làm làm hài lòng Ngài. Ôi Allah, hãy làm cho cuộc hành trình này trở nên dễ dàng đối với chúng tôi và rút ngắn khoảng cách. Ôi Allah, Ngài là Người đồng hành trên cuộc hành trình và là Người bảo vệ gia đình.", "Khi bắt đầu cuộc hành trình, sau 'Subhanalladhi sakhkhara'.", "Dua du lịch Sunnah hoàn chỉnh."),
        "dua_return_travel" to DuaText("Trở về từ chuyến du lịch", "Chúng tôi đang trở về, ăn năn, thờ phượng và ca ngợi Chúa của chúng tôi.", "Khi trở về từ một cuộc hành trình.", "Nhà tiên tri ﷺ đã nói điều này khi trở về sau một cuộc hành trình."),
        "dua_farewell_traveller" to DuaText("Chia tay một lữ khách", "Tôi giao phó cho Allah tôn giáo của bạn, sự tin tưởng của bạn và kết quả việc làm của bạn.", "Khi chia tay một lữ khách.", "Những gì được giao phó cho Allah sẽ không bao giờ bị mất."),
        "dua_entering_town" to DuaText("Dừng lại ở một địa điểm", "Tôi tìm nơi ẩn náu trong những lời nói hoàn hảo của Allah để tránh khỏi sự xấu xa của tất cả những gì Ngài đã tạo ra.", "Khi dừng lại ở một địa điểm hoặc đến một thị trấn mới.", "Sẽ không có gì có thể làm hại anh ta cho đến khi anh ta rời khỏi đó."),
        "dua_boarding_ship" to DuaText("Lên tàu/phương tiện", "Nhân danh Allah, nó chèo thuyền và thả neo. Quả thật, Chúa của tôi là Đấng Tha thứ, Rất mực Khoan dung.", "Khi lên tàu hoặc phương tiện - lời của Nhà tiên tri Nuh (AS).", "Một câu Kinh Qur'an - dua của chiếc hòm (AS) của Nuh."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar với Hayyul-Qayyum", "Tôi cầu xin sự tha thứ từ Allah, ngoài Ngài ra không có vị thần nào, Đấng Hằng Sống, Đấng Duy trì, và tôi hướng về Ngài để ăn năn.", "Để sám hối.", "Tội lỗi của anh ta được tha thứ ngay cả khi anh ta đã chạy trốn khỏi chiến trường."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "Lạy Chúa, xin tha thứ và thương xót, vì Chúa là người tốt nhất trong số những người thể hiện lòng thương xót.", "A dua Kinh Qur'an - cho sự tha thứ và lòng thương xót.", "Câu thơ cuối cùng của Surah al-Mu'minun."),
        "dua_majlis_kaffarah" to DuaText("Kaffarat al-Majlis", "Lạy Allah, xin vinh danh Ngài và ca ngợi Ngài. Tôi làm chứng rằng không có thần nào ngoại trừ Ngài. Tôi cầu xin sự tha thứ của Ngài và quay về với Ngài để ăn năn.", "Khi đứng dậy từ một cuộc tụ tập.", "Nó trở thành một sự đền tội cho bất cứ điều gì sai trái đã được nói ra trong cuộc họp."),
        "dua_jami_forgiveness" to DuaText("Sự tha thứ toàn diện", "Ôi Allah, hãy tha thứ cho những lỗi lầm, sự thiếu hiểu biết, sự quá đáng của tôi trong công việc của tôi và tất cả những điều mà Ngài biết rõ hơn tôi.", "Một bản dua toàn diện của Nhà tiên tri ﷺ.", "Nhà tiên tri ﷺ đã từng làm bộ dua này."),
        "dua_parents_nuh" to DuaText("Dua của Nuh (AS) dành cho phụ huynh", "Lạy Chúa, xin tha thứ cho con, cha mẹ con, bất cứ ai vào nhà con với tư cách là một tín đồ, và tất cả những người nam nữ có đức tin.", "Đối với cha mẹ và các tín hữu.", "Dua của nhà tiên tri Nuh (AS)."),
        "dua_shukr_parents" to DuaText("Tri Ân Cha Mẹ & Con Cái Chính Nghĩa", "Lạy Chúa, xin cho con biết ơn Chúa vì ân huệ Chúa đã ban cho con và cha mẹ con, và làm những việc công bình đẹp lòng Chúa, và làm cho con cháu con trở nên công chính. Tôi hướng về Ngài để ăn năn và tôi nằm trong số những người quy phục.", "Dua Kinh Qur'an đạt đến tuổi bốn mươi.", "Lòng biết ơn, việc tốt và sự công bình của con cái - tất cả đều có trong một dua."),
        "dua_intimacy" to DuaText("Trước Quan Hệ Hôn Nhân", "Nhân danh Allah. Ôi Allah, hãy giữ Shaytan tránh xa chúng tôi và giữ Shaytan tránh xa những gì (trẻ em) mà bạn ban cho chúng tôi.", "Trước quan hệ hôn nhân.", "Nếu một đứa trẻ bị ra lệnh, Shaytan sẽ không bao giờ làm hại nó."),
        "dua_ibrahim_children_protection" to DuaText("Bảo vệ Gia đình và Trẻ em", "Lạy Chúa, xin hãy làm cho thành phố này được an toàn và giữ cho tôi và các con tôi tránh xa việc thờ thần tượng.", "Dua của Nhà tiên tri Ibrahim (AS) - vì sự an toàn của thành phố và con cái của ông.", "Một dua cho công ty còn lại trên tawhid."),
        "dua_drinking_milk" to DuaText("Khi uống sữa", "Ôi Allah, hãy ban phước cho chúng tôi và cho chúng tôi nhiều hơn nữa.", "Khi uống sữa.", "Sữa đủ dùng làm đồ ăn và đồ uống."),
        "dua_iftar_host" to DuaText("Khi ăn chay với người khác", "Cầu mong những người đang ăn chay cùng ăn chay với bạn, cầu mong những người công chính ăn đồ ăn của bạn và cầu mong các thiên thần cầu nguyện cho bạn.", "Khi nhịn ăn ở nhà ai đó.", "ﷺ dua của Nhà tiên tri dành cho chủ nhà."),
    )
}
